import {
  BadRequestException,
  Body,
  Controller,
  Get,
  Param,
  Post,
  Put,
  Query,
} from '@nestjs/common';
import { RadioService } from './radio.service';
import { SongExecutionEngine } from './song-execution.engine';
import {
  NowPlayingPublisherService,
  type NowPlayingConsumerPayload,
} from './now-playing-publisher.service';
import { PalazzoRadioTelemetryService } from './palazzo-telemetry.service';
import { RadioOutputConfidenceService } from './radio-output-confidence.service';
import { SongSimilarityService } from './song-similarity.service';
import type { RadioSettingsPayload } from './radio.service';
import { ALCANTARA_PERMISSIONS } from '../auth/permissions';
import { RequirePermission } from '../auth/require-permission.decorator';

@Controller('radio')
@RequirePermission(ALCANTARA_PERMISSIONS.radio.read)
export class RadioController {
  constructor(
    private readonly radioService: RadioService,
    private readonly songExecutionEngine: SongExecutionEngine,
    private readonly nowPlayingPublisherService: NowPlayingPublisherService,
    private readonly palazzoTelemetry: PalazzoRadioTelemetryService,
    private readonly outputConfidence: RadioOutputConfidenceService,
    private readonly songSimilarity: SongSimilarityService,
  ) {}

  @Get(':programId/similarity/coverage')
  async similarityCoverage(@Param('programId') programId: string) {
    return this.songSimilarity.getCoverage(programId);
  }

  @Get(':programId/similarity/decisions')
  async similarityDecisions(
    @Param('programId') programId: string,
    @Query('limit') limit?: string,
  ) {
    return this.songSimilarity.listDecisions(
      programId,
      limit ? Number(limit) : 50,
    );
  }

  @Get(':programId/similarity/export')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.manage)
  async similarityExport(
    @Param('programId') programId: string,
    @Query('scope') scope?: string,
    @Query('missingOnly') missingOnly?: string,
  ) {
    if (scope !== 'sequence' && scope !== 'catalog')
      throw new BadRequestException('scope must be sequence or catalog');
    return this.songSimilarity.exportSongs(
      programId,
      scope,
      missingOnly === 'true',
    );
  }

  @Post(':programId/similarity/embeddings')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.manage)
  async similarityUpload(@Body() body: unknown) {
    return this.songSimilarity.storeEmbeddings(body);
  }

  @Get(':programId/settings')
  async getSettings(@Param('programId') programId: string) {
    return this.radioService.getRadioSettings(programId);
  }

  @Put(':programId/settings')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.manage)
  async updateSettings(
    @Param('programId') programId: string,
    @Body() data: RadioSettingsPayload,
  ) {
    const previous = await this.radioService.getRadioSettings(programId);
    const result = await this.radioService.updateRadioSettings(programId, data);
    if (
      data.similarityMode !== undefined ||
      data.similarityThreshold !== undefined ||
      data.similarityWindowSeconds !== undefined ||
      data.similarityPool !== undefined
    ) {
      await this.songSimilarity.onSettingsChanged();
    }
    if (
      previous?.palazzoUrl !== result.palazzoUrl ||
      previous?.enabled !== result.enabled
    ) {
      await this.palazzoTelemetry.handleRadioSettingsChanged(programId);
    }
    return result;
  }

  @Get(':programId/palazzo-status')
  async getPalazzoStatus(@Param('programId') programId: string) {
    return this.palazzoTelemetry.getStatus(programId);
  }

  @Get(':programId/output-confidence')
  async getOutputConfidence(@Param('programId') programId: string) {
    await this.radioService.getRadioSettings(programId);
    return this.outputConfidence.get(programId);
  }

  @Get(':programId/recovery')
  async getRecovery(@Param('programId') programId: string) {
    return this.radioService.getRecoveryStatus(programId);
  }

  @Post(':programId/recovery/prepare')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.manage)
  async prepareRecovery(
    @Param('programId') programId: string,
    @Body() body: { songIds?: number[] },
  ) {
    return this.radioService.prepareRecoveryPlaylist(
      programId,
      body.songIds as number[],
    );
  }

  @Post(':programId/recovery/start')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.operate)
  async startRecovery(@Param('programId') programId: string) {
    return this.radioService.setRecoveryAutomation(programId, 'start');
  }

  @Post(':programId/recovery/stop')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.operate)
  async stopRecovery(@Param('programId') programId: string) {
    return this.radioService.setRecoveryAutomation(programId, 'stop');
  }

  @Get(':programId/now-playing-consumers')
  async listNowPlayingConsumers(@Param('programId') programId: string) {
    return this.nowPlayingPublisherService.listConsumers(programId);
  }

  @Get(':programId/now-playing-publishing')
  nowPlayingPublishing() {
    return { publishing: this.nowPlayingPublisherService.outboundPublishing() };
  }

  @Put(':programId/now-playing-consumers')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.manage)
  async replaceNowPlayingConsumers(
    @Param('programId') programId: string,
    @Body() data: { consumers?: NowPlayingConsumerPayload[] },
  ) {
    if (!Array.isArray(data.consumers)) {
      throw new BadRequestException('consumers must be an array');
    }
    try {
      return await this.nowPlayingPublisherService.replaceConsumers(
        programId,
        data.consumers,
      );
    } catch (err) {
      throw new BadRequestException(
        err instanceof Error ? err.message : String(err),
      );
    }
  }

  @Post(':programId/song')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.operate)
  async playSong(
    @Param('programId') programId: string,
    @Body()
    data: {
      audioUrl: string;
      title?: string;
      artist?: string;
      coverUrl?: string;
      durationMs?: number;
      songId?: number;
    },
  ) {
    if (!data.audioUrl) {
      throw new BadRequestException('audioUrl is required');
    }
    this.songExecutionEngine.handleManualSong(
      programId,
      data.audioUrl,
      data.title,
      data.artist,
      data.durationMs,
      data.coverUrl,
      data.songId,
    );
    return { ok: true };
  }

  @Post(':programId/song/stop')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.operate)
  async stopSong(@Param('programId') programId: string) {
    await this.radioService.stopSong(programId);
    this.songExecutionEngine.handleStopSong(programId);
    return { ok: true };
  }

  @Post(':programId/instant')
  @RequirePermission(ALCANTARA_PERMISSIONS.radio.operate)
  async playInstant(
    @Param('programId') programId: string,
    @Body() data: { audioUrl: string; instantId: number; volume?: number },
  ) {
    if (!data.audioUrl) {
      throw new BadRequestException('audioUrl is required');
    }
