/**
 * Why a program has no Palazzo telemetry client (gaulatti/alcantara#257). A
 * closed, additive set: a consumer ignores a value it does not know.
 */
export type PalazzoUnavailableReason =
  | 'not-configured'
  | 'disabled'
  | 'url-rejected'
  | 'deploy-candidate';

/**
 * What `GET /radio/:programId/palazzo-status` answers when the program has no
 * telemetry client, in place of the former `null`. It keeps the fields an older
 * console reads (`connection`, `degraded`, `detail`); `reason` is absent only
 * for the brief window where the client has not started yet. `palazzoUrl` is
 * always empty: a rejected URL is never echoed.
 */
export interface PalazzoUnavailableStatus extends Omit<
  PalazzoProgramStatus,
  'programType' | 'connection'
> {
  programType: PalazzoProgramType | null;
  connection: 'unavailable';
  reason?: PalazzoUnavailableReason;
}

export interface PalazzoTrackStartedData {
  playbackRequestId: string;
  title: string | null;
  artist: string | null;
  coverUrl: string | null;
  url?: string;
  liquidsoapSequence: number;
}

export interface PalazzoTrackEndedData {
  playbackRequestId: string;

/**
 * Why the backend has no Palazzo engine for a program (gaulatti/alcantara#257).
 * `GET /radio/:programId/palazzo-status` carries an optional `reason`; this
 * closed set is additive on the backend, so an unknown value, a missing one and
 * a null body all read as no reason and keep today's wording.
 */
const REASON_TEXT: Record<string, string> = {
  "not-configured": "not configured",
  disabled: "disabled in settings",
  "url-rejected": "URL not allowed",
  "deploy-candidate": "deploy candidate",
};

export function palazzoReasonText(reason: unknown): string | null {
  return typeof reason === "string" &&
    Object.prototype.hasOwnProperty.call(REASON_TEXT, reason)
    ? REASON_TEXT[reason]
    : null;
}

/** "Engine unavailable", with the reason in plain words when the backend gave a known one. */
export function engineUnavailableLabel(
  status: { reason?: unknown } | null | undefined,
): string {
  const text = palazzoReasonText(status?.reason);
  return text ? `Engine unavailable: ${text}` : "Engine unavailable";
}

